mapper.update:
update app_user
set status = #{status},
    review_note = #{reviewNote,jdbcType=VARCHAR},
    reviewed_at = now(),
    reviewed_by = #{reviewedBy,jdbcType=BIGINT}
where id = #{id}

mapper.select:
select  from app_user

order by case status when 'pending' then 0 when 'rejected' then 2 else 1 end, id desc
limit #{offset}, #{size}
